\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
tick label style={font=\footnotesize},
        label style={font=\small},
        legend style={font=\footnotesize},
        tick style={line width=0.8pt, color=black},
        axis line style = thick,
        axis y line = center,
        axis x line = middle,
        %axis equal,
        %grid = both,
        xmin = -2.0,
        xmax = 1.0,
        ymin = -4.5,
        ymax = 1.5,
        xtick = {-1},
        ytick = {-2},
        xlabel style={below right},
		ylabel style={above right},
		%% Here, we can control the positioning of each individual tick.
		x tick label style={xshift={(\tick==-2)*-7pt}},
		y tick label style={yshift={(\tick==-4)*0pt}},
		every axis x label/.style={
			at={(ticklabel* cs:1.02)},
			anchor=west,
		},
		every axis y label/.style={
			at={(ticklabel* cs:1.02)},
			anchor=south,
		}
]

% Graphic
\addplot [domain=-6:6,samples=100,color=red,line width=1pt]{-x^3-3*x^2-4*x-2};

\end{axis}

\end{tikzpicture}
\end{document}

